from qiskit import QuantumCircuit

def build_oracle(qc, qr, ancillas):
    n = len(qr)
    if n == 0:
        return
    # Flip all qubits: |0...0> -> |1...1>
    for qubit in qr:
        qc.x(qubit)
    if len(ancillas) > 0:
        target = ancillas[0]
        # Use 'v-chain' mode which reliably handles n controls with fewer ancillas
        qc.mcx(qr, target, ancillas[1:], mode='v-chain')
        qc.z(target)                   # flip phase if all controls were 1
        qc.mcx(qr, target, ancillas[1:], mode='v-chain')  # uncompute
